import SwiftUI
import Supabase


struct ManualFoodEntryView: View {
    
    // Name entered by the user
    @State private var foodName = ""
    
    // Tracks whether a manual food is currently being saved
    @State private var isSaving = false

    // Message shown after saving or if something goes wrong
    @State private var saveMessage = ""

    // Connects this screen to the food_logs Supabase service
    private let foodLogService = FoodLogService()
    
    // Nutrition values entered by the user
    @State private var calories = ""
    @State private var protein = ""
    @State private var carbs = ""
    @State private var fat = ""
    
    // Optional additional nutrition values
    @State private var fiber = ""
    @State private var sugar = ""
    @State private var saturatedFat = ""
    @State private var transFat = ""
    @State private var sodium = ""
    @State private var cholesterol = ""
    
    // Number of servings eaten
    @State private var servings: Double = 1.0
    
    // Meal selected by the user
    @State private var mealType = "breakfast"
    
    // Date and time the user ate the food
    @State private var consumedAt = Date()
    
    private let mealTypes = [
        "breakfast",
        "lunch",
        "dinner",
        "snack"
    ]
    
    
    var body: some View {
        
        Form {
            
            // ---------------------------------
            // MARK: Food Information
            // ---------------------------------
            
            Section("Food") {
                
                TextField(
                    "Food name",
                    text: $foodName
                )
            }
            
            
            // ---------------------------------
            // MARK: Nutrition Information
            // ---------------------------------
            
            Section("Nutrition") {
                
                TextField(
                    "Calories",
                    text: $calories
                )
                .keyboardType(.decimalPad)
                
                
                TextField(
                    "Protein (g)",
                    text: $protein
                )
                .keyboardType(.decimalPad)
                
                
                TextField(
                    "Carbohydrates (g)",
                    text: $carbs
                )
                .keyboardType(.decimalPad)
                
                
                TextField(
                    "Fat (g)",
                    text: $fat
                )
                .keyboardType(.decimalPad)
                
                TextField(
                    "Fiber (g)",
                    text: $fiber
                )
                .keyboardType(.decimalPad)

                TextField(
                    "Sugar (g)",
                    text: $sugar
                )
                .keyboardType(.decimalPad)

                TextField(
                    "Saturated Fat (g)",
                    text: $saturatedFat
                )
                .keyboardType(.decimalPad)

                TextField(
                    "Trans Fat (g)",
                    text: $transFat
                )
                .keyboardType(.decimalPad)

                TextField(
                    "Sodium (mg)",
                    text: $sodium
                )
                .keyboardType(.decimalPad)

                TextField(
                    "Cholesterol (mg)",
                    text: $cholesterol
                )
                .keyboardType(.decimalPad)
            }
            
            
            // ---------------------------------
            // MARK: Serving Information
            // ---------------------------------
            
            Section("Serving") {
                
                Stepper(
                    value: $servings,
                    in: 0.5...10.0,
                    step: 0.5
                ) {
                    
                    HStack {
                        
                        Text("Servings")
                        
                        Spacer()
                        
                        Text(
                            servings.formatted(
                                .number.precision(
                                    .fractionLength(1)
                                )
                            )
                        )
                    }
                }
            }
            
            
            // ---------------------------------
            // MARK: Meal
            // ---------------------------------
            
            Section("Meal") {
                
                Picker(
                    "Meal Type",
                    selection: $mealType
                ) {
                    
                    ForEach(
                        mealTypes,
                        id: \.self
                    ) { meal in
                        
                        Text(meal.capitalized)
                            .tag(meal)
                    }
                }
            }
            
            // ---------------------------------
            // MARK: When Eaten
            // ---------------------------------

            Section("When Eaten") {
                
                DatePicker(
                    "Date and Time",
                    selection: $consumedAt,
                    displayedComponents: [
                        .date,
                        .hourAndMinute
                    ]
                )
            }
            
            Section {
                
                Button {
                    
                    Task {
                        await saveManualFood()
                    }
                    
                } label: {
                    
                    if isSaving {
                        
                        HStack {
                            
                            Spacer()
                            
                            ProgressView()
                            
                            Spacer()
                        }
                        
                    } else {
                        
                        Text("Log Food")
                            .frame(
                                maxWidth: .infinity,
                                alignment: .center
                            )
                    }
                }
                .disabled(isSaving)
                
                
                if !saveMessage.isEmpty {
                    
                    Text(saveMessage)
                        .font(.footnote)
                        .foregroundColor(.secondary)
                }
            }
        }
        .navigationTitle("Manual Food Entry")
    }
    
    @MainActor
    private func saveManualFood() async {
        
        // Clear any old message
        saveMessage = ""
        
        
        // Remove accidental spaces before/after the food name
        let trimmedName =
            foodName.trimmingCharacters(
                in: .whitespacesAndNewlines
            )
        
        
        // Make sure a food name was entered
        guard !trimmedName.isEmpty else {
            
            saveMessage = "Enter a food name."
            return
        }
        
        
        // Convert calories from String to Double
        guard let caloriesPerServing = Double(calories),
              caloriesPerServing >= 0 else {
            
            saveMessage = "Enter a valid calorie amount."
            return
        }
        
        
        // Macros are optional.
        // If left blank, use 0.
        
        let proteinPerServing =
            protein.isEmpty
            ? 0
            : Double(protein)
        
        let carbsPerServing =
            carbs.isEmpty
            ? 0
            : Double(carbs)
        
        let fatPerServing =
            fat.isEmpty
            ? 0
            : Double(fat)
        
        
        // Make sure any macros that were entered are valid numbers
        guard let proteinPerServing,
              let carbsPerServing,
              let fatPerServing,
              proteinPerServing >= 0,
              carbsPerServing >= 0,
              fatPerServing >= 0 else {
            
            saveMessage = "Enter valid macro amounts."
            return
        }
        
        // Additional nutrition values are optional.
        // Blank means unknown, while 0 means truly zero.
        let fiberPerServing =
            fiber.isEmpty
            ? nil
            : Double(fiber)

        let sugarPerServing =
            sugar.isEmpty
            ? nil
            : Double(sugar)

        let saturatedFatPerServing =
            saturatedFat.isEmpty
            ? nil
            : Double(saturatedFat)

        let transFatPerServing =
            transFat.isEmpty
            ? nil
            : Double(transFat)

        let sodiumPerServing =
            sodium.isEmpty
            ? nil
            : Double(sodium)

        let cholesterolPerServing =
            cholesterol.isEmpty
            ? nil
            : Double(cholesterol)
        
        if let fiberPerServing,
           fiberPerServing < 0 {
            
            saveMessage =
                "Enter a valid fiber amount."
            return
        }

        if let sugarPerServing,
           sugarPerServing < 0 {
            
            saveMessage =
                "Enter a valid sugar amount."
            return
        }

        if let saturatedFatPerServing,
           saturatedFatPerServing < 0 {
            
            saveMessage =
                "Enter a valid saturated fat amount."
            return
        }

        if let transFatPerServing,
           transFatPerServing < 0 {
            
            saveMessage =
                "Enter a valid trans fat amount."
            return
        }

        if let sodiumPerServing,
           sodiumPerServing < 0 {
            
            saveMessage =
                "Enter a valid sodium amount."
            return
        }

        if let cholesterolPerServing,
           cholesterolPerServing < 0 {
            
            saveMessage =
                "Enter a valid cholesterol amount."
            return
        }
        
        
        // Get the currently logged-in Supabase user
        guard let currentUserID =
                supabase.auth.currentUser?.id else {
            
            saveMessage =
                "You must be logged in to log food."
            
            return
        }
        
        // Convert the selected eaten date into a timestamp
        let dateFormatter = ISO8601DateFormatter()

        let consumedAtTimestamp =
            dateFormatter.string(
                from: consumedAt
            )
        
        // Create the row that will be sent to food_logs
        let newFoodLog = NewFoodLog(
            
            user_id: currentUserID,
            
            source: "manual",
            
            fdc_id: nil,
            
            food_name: trimmedName,
            
            brand_name: nil,
            
            serving_amount: servings,
            
            serving_unit: "serving",
            
            calories:
                caloriesPerServing * servings,
            
            protein_g:
                proteinPerServing * servings,
            
            carbs_g:
                carbsPerServing * servings,
            
            fat_g:
                fatPerServing * servings,
            
            fiber_g:
                fiberPerServing.map {
                    $0 * servings
                },

            sugar_g:
                sugarPerServing.map {
                    $0 * servings
                },

            saturated_fat_g:
                saturatedFatPerServing.map {
                    $0 * servings
                },

            trans_fat_g:
                transFatPerServing.map {
                    $0 * servings
                },

            sodium_mg:
                sodiumPerServing.map {
                    $0 * servings
                },

            cholesterol_mg:
                cholesterolPerServing.map {
                    $0 * servings
                },
            
            meal_type: mealType,
            
            consumed_at: consumedAtTimestamp
        )
        
        
        // Prevent repeated button presses while saving
        isSaving = true
        
        defer {
            isSaving = false
        }
        
        
        do {
            
            try await foodLogService.saveFoodLog(
                newFoodLog
            )
            
            saveMessage =
                "Food logged successfully."
            
            
            // Reset the form
            foodName = ""
            calories = ""
            protein = ""
            carbs = ""
            fat = ""
            fiber = ""
            sugar = ""
            saturatedFat = ""
            transFat = ""
            sodium = ""
            cholesterol = ""
            
            servings = 1.0
            mealType = "breakfast"
            consumedAt = Date()
            
        } catch is CancellationError {
            
            print(
                "Manual food logging was cancelled."
            )
            
        } catch {
            
            saveMessage = "Could not log food."
            
            print(
                "Manual food logging failed: \(error.localizedDescription)"
            )
        }
    }
}
